<?php
/** TEMP PS S1676 run s — partijos v1.4 + gavimo-perrusiavimas v1.0 DEPLOY (D); DRY kandidatai (T). */
add_action('init', function(){
  if (!isset($_GET['ps_s1676s'])) return; global $wpdb; $p=$wpdb->prefix; $F=$_GET['ps_s1676s']; $o=array('v'=>'S1676 s','faze'=>$F);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $bk=wp_upload_dir()['basedir'].'/ps-backups/';
  if($F==='D'){
    $f1=WPMU_PLUGIN_DIR.'/petshop-partijos.php'; $f2=WPMU_PLUGIN_DIR.'/petshop-gavimo-perrusiavimas.php';
    $k1=base64_decode(''); $k2=base64_decode('');
    if(md5_file($f1)!=='b1a8309c74992f242f9f63b727e8e431'){ $o['STOP']='partijos gyvas md5 '.md5_file($f1); }
    elseif(md5($k1)!=='7372f8eebf4218afe9786608b7b05448'||md5($k2)!=='4c8baa2fef2cffb4515686e26040526f'){ $o['STOP']='b64 md5'; }
    elseif(@token_get_all($k1,TOKEN_PARSE)===false||@token_get_all($k2,TOKEN_PARSE)===false){ $o['STOP']='sintaksė'; }
    else { copy($f1,$bk.'petshop-partijos.php.bak_s1676'); file_put_contents($f1,$k1); file_put_contents($f2,$k2); $o['md5']=array(md5_file($f1),md5_file($f2));
      $r=wp_remote_get(home_url('/?ps_ping_s1676s='.time()),array('timeout'=>25,'sslverify'=>false)); $c=is_wp_error($r)?'ERR':wp_remote_retrieve_response_code($r); $o['ping']=$c;
      if(is_wp_error($r)||$c>=500){ copy($bk.'petshop-partijos.php.bak_s1676',$f1); unlink($f2); $o['ROLLBACK']=1; } }
  }
  if($F==='T'){
    $o['klases']=array(class_exists('Petshop_Gavimo_Perrusiavimas'),has_action('ps_partija_priimta'));
    // visos processing eilutės ne-AV: kandidatai pagal prekę
    $rows=$wpdb->get_results("SELECT DISTINCT l.product_id FROM {$p}wc_order_product_lookup l JOIN {$p}wc_orders o ON o.id=l.order_id WHERE o.type='shop_order' AND o.status='wc-processing'",ARRAY_A);
    foreach($rows as $r){ $pid=(int)$r['product_id']; $b=Petshop_AV_Source::dp($pid); $base=$b?$b['base']:$pid; $d=Petshop_Gavimo_Perrusiavimas::perrusiuoti($base,true); if($d['eil']) $o['dry'][$base]=array_map(function($e){return $e['nr'].' iid'.$e['iid'].' pid'.$e['pid'].' q'.$e['q'].' src='.$e['buvo'];},$d['eil']); }
    $o['dry_17707']=Petshop_Gavimo_Perrusiavimas::perrusiuoti(17707,true);
  }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
});
